SELECT COUNT(*)
FROM TB_SEARCH_AD_KEYWORD
WHERE del_yn = 'N'

    AND keyword LIKE CONCAT('%', #{keyword}, '%')


    AND ncc_keyword_id = #{nccKeywordId}


    AND use_yn = #{useYn}

